1	package registry
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"math/big"
7		"sort"
8		"strings"
9	)
10	
11	// ---- 版税规则设置 ----
12	
13	// normalizeShares 校验并规范化规则份额：收款账户去重、比例范围与合计
14	// 校验（均为无状态的参数校验），并按收款账户排序，使同一规则与书写
15	// 顺序无关。返回规范化后的份额；参数不合法时返回 ErrInvalidArgument。
16	func normalizeShares(shares []RoyaltyShare) ([]royaltyShare, error) {
17		seen := make(map[string]bool, len(shares))
18		out := make([]royaltyShare, 0, len(shares))
19		var total int64
20		for _, sh := range shares {
21			if strings.TrimSpace(sh.AccountID) == "" {
22				return nil, fmt.Errorf("%w: 版税收款账户不能为空", ErrInvalidArgument)
23			}
24			if sh.Rate < 1 || sh.Rate > RoyaltyRateBase {
25				return nil, fmt.Errorf("%w: 账户 %s 的版税比例 %d 不在 1..%d 内",
26					ErrInvalidArgument, sh.AccountID, sh.Rate, RoyaltyRateBase)
27			}
28			if seen[sh.AccountID] {
29				return nil, fmt.Errorf("%w: 版税收款账户 %s 重复", ErrInvalidArgument, sh.AccountID)
30			}
31			seen[sh.AccountID] = true
32			total += sh.Rate
33			out = append(out, royaltyShare{AccountID: sh.AccountID, Rate: sh.Rate})
34		}
35		if total > RoyaltyRateBase {
36			return nil, fmt.Errorf("%w: 版税比例合计 %d 超过 %d", ErrInvalidArgument, total, RoyaltyRateBase)
37		}
38		sort.Slice(out, func(i, j int) bool { return out[i].AccountID < out[j].AccountID })
39		return out, nil
40	}
41	
42	func (req SetRoyaltyRequest) validatePresent() error {
43		missing := []string{}
44		if strings.TrimSpace(req.Operator) == "" {
45			missing = append(missing, "operator")
46		}
47		if strings.TrimSpace(req.Reason) == "" {
48			missing = append(missing, "reason")
49		}
50		if strings.TrimSpace(req.RequestID) == "" {
51			missing = append(missing, "request_id")
52		}
53		if strings.TrimSpace(req.SeriesID) == "" {
54			missing = append(missing, "series_id")
55		}
56		if len(missing) > 0 {
57			return fmt.Errorf("%w: 设置版税规则请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
58		}
59		return nil
60	}
61	
62	func setRoyaltyParamsSig(req SetRoyaltyRequest, shares []royaltyShare) string {
63		b, _ := json.Marshal(struct {
64			Kind     string         `json:"kind"`
65			SeriesID string         `json:"series_id"`
66			Shares   []royaltyShare `json:"shares"`
67			Reason   string         `json:"reason"`
68		}{"royalty_set", req.SeriesID, shares, req.Reason})
69		return string(b)
70	}
71	
72	// SetRoyalty 设置或清空系列的版税规则，并记录本次变更的操作者、原因、
73	// 请求号与前后内容。只有系列创建账户（且可用）可以设置；每个收款账户
74	// 只能出现一次，比例是 1..10000 的整数（万分之一），合计不超过 10000；
75	// Shares 为空表示清空规则、不收版税。首次成功发行后规则固定（未设置
76	// 即固定为无版税），封存后同样拒绝设置。
77	//
78	// 请求号与发行、转让等操作共用同一操作者的请求号范围：相同业务参数
79	// 重提返回首次结果，参数不同返回 ErrRequestConflict；参数错误与引用
80	// 不存在不占用请求号。
81	//
82	// 成功与状态类拒绝都以保存完成为准：本次结果尚未写入原登记册而保存失败
83	// （如数据位置暂时无法写入）时，返回实际保存错误，不报告设置成功，也不
84	// 只返回原业务拒绝；结果为空（系列编号、份额与业务错误均为空，不标回放），
85	// 请求号与变更序号都不被这次未保存的操作消耗。即使失败后原数据暂时无法
86	// 读取、状态未能按磁盘重建，这次操作也不留下任何规则变化、变更记录或
87	// 请求号占用，后续其他操作成功保存也不会把这次未保存的内容带进登记册。
88	// 保存条件恢复后用完全相同的请求重提，按当时的业务状态重新判断：拒绝
89	// 条件仍在则重新保存此次拒绝并返回对应业务错误（首次重提不标回放），
90	// 状态已满足请求则正常设置。
91	func (r *Registry) SetRoyalty(req SetRoyaltyRequest) (SetRoyaltyResult, error) {
92		if err := req.validatePresent(); err != nil {
93			return SetRoyaltyResult{}, err
94		}
95		// 份额的形状校验（重复账户、比例范围、合计）不依赖状态，在取锁前
96		// 完成；不合法时原规则不变，也不占用请求号。
97		shares, err := normalizeShares(req.Shares)
98		if err != nil {
99			return SetRoyaltyResult{SeriesID: req.SeriesID, Err: err}, err
100		}
101		r.mu.Lock()
102		defer r.mu.Unlock()
103		if err := r.checkOpen(); err != nil {
104			return SetRoyaltyResult{}, err
105		}
106	
107		key := requestKey(req.Operator, req.RequestID)
108		sig := setRoyaltyParamsSig(req, shares)
109		if prev, ok := r.state.Requests[key]; ok {
110			return r.replaySetRoyalty(prev, sig)
111		}
112	
113		if bizErr := r.checkSetRoyalty(req, shares); bizErr != nil {
114			if !isValidationErr(bizErr) {
115				// 状态类业务拒绝（停用、无权、封存、已固定等）占用请求号并
116				// 落盘；参数错误与引用不存在不占用。
117				r.state.Requests[key] = request{
118					Operator: req.Operator, RequestID: req.RequestID, Kind: "royalty_set",
119					Params: sig, Rejected: true, Reason: errCode(bizErr),
120					SeriesID: req.SeriesID,
121				}
122				if err := r.commit(); err != nil {
123					// 拒绝结果落盘失败：这次拒绝没有被记住，与发行、转让一致——
124					// 不能只用业务错误掩盖保存错误，调用者稍后用原请求重提时
125					// 必须按当时状态重新判断，而不是回放一个实际没有保存的
126					// 拒绝。commit 失败时已按磁盘内容重建状态，请求记录随之
127					// 撤销；此处再删一次以覆盖磁盘暂时不可读、状态未能重建
128					// 的情形。整体返回空结果：系列编号、份额为空，不标回放，
129					// 结果中业务错误为空，error 保留实际写入错误。
130					delete(r.state.Requests, key)
131					return SetRoyaltyResult{}, err
132				}
133			}
134			return SetRoyaltyResult{SeriesID: req.SeriesID, Err: bizErr}, bizErr
135		}
136	
137		s := r.state.Series[req.SeriesID]
138		before := append([]royaltyShare(nil), s.Royalty...)
139		// 回滚基点：保存失败且磁盘暂时不可读、状态未能按磁盘重建时，本次
140		// 未保存的规则变化、变更记录与请求号占用都必须显式撤销，否则后续
141		// 任何一次成功保存都会把这份未保存的内容带进登记册。
142		prevRoyaltySeq := r.state.NextRoyaltySeq
143		prevEvents := len(r.state.RoyaltyEvents)
144		s.Royalty = shares
145		r.state.Series[req.SeriesID] = s
146		seq := prevRoyaltySeq + 1
147		r.state.NextRoyaltySeq = seq
148		r.state.RoyaltyEvents = append(r.state.RoyaltyEvents, royaltyEvent{
149			Seq: seq, SeriesID: req.SeriesID, Operator: req.Operator,
150			Reason: req.Reason, RequestID: req.RequestID,
151			Before: before, After: append([]royaltyShare(nil), shares...),
152			OccurredAt: r.now(),
153		})
154		r.state.Requests[key] = request{
155			Operator: req.Operator, RequestID: req.RequestID, Kind: "royalty_set",
156			Params: sig, SeriesID: req.SeriesID, Shares: shares,
157		}
158		if err := r.commit(); err != nil {
159			// commit 失败时已尝试按磁盘内容重建状态：重建成功则本次改动已
160			// 随旧状态整体撤销（请求记录不存在），无需再动；磁盘暂时不可读、
161			// 状态未能重建时请求记录仍在，据此把本次未保存的改动全部撤销——
162			// 恢复原规则（原本没有规则的系列恢复为空规则）、撤去变更记录、
163			// 归还变更序号与请求号。
164			if _, ok := r.state.Requests[key]; ok {
165				delete(r.state.Requests, key)
166				s := r.state.Series[req.SeriesID]
167				s.Royalty = before
168				r.state.Series[req.SeriesID] = s
169				r.state.RoyaltyEvents = r.state.RoyaltyEvents[:prevEvents]
170				r.state.NextRoyaltySeq = prevRoyaltySeq
171			}
172			return SetRoyaltyResult{}, err
173		}
174		return SetRoyaltyResult{SeriesID: req.SeriesID, Shares: publicShares(shares)}, nil
175	}
176	
177	func (r *Registry) checkSetRoyalty(req SetRoyaltyRequest, shares []royaltyShare) error {
178		op, ok := r.state.Accounts[req.Operator]
179		if !ok {
180			return fmt.Errorf("%w: 操作者账户 %s", ErrNotFound, req.Operator)
181		}
182		if !op.Active {
183			return fmt.Errorf("%w: 操作者账户 %s", ErrAccountInactive, req.Operator)
184		}
185		s, ok := r.state.Series[req.SeriesID]
186		if !ok {
187			return fmt.Errorf("%w: 系列 %s", ErrNotFound, req.SeriesID)
188		}
189		if s.CreatorID != req.Operator {
190			return fmt.Errorf("%w: 只有创建账户 %s 可以设置系列 %s 的版税规则",
191				ErrForbidden, s.CreatorID, req.SeriesID)
192		}
193		if s.Sealed {
194			return fmt.Errorf("%w: 系列 %s 已封存，不能设置版税规则", ErrSeriesSealed, req.SeriesID)
195		}
196		// 首次成功发行后规则固定：系列中已存在藏品即视为已固定。
197		for _, it := range r.state.Items {
198			if it.SeriesID == req.SeriesID {
199				return fmt.Errorf("%w: 系列 %s 已发行藏品，版税规则不能再设置",
200					ErrRoyaltyFrozen, req.SeriesID)
201			}
202		}
203		for _, sh := range shares {
204			payee, ok := r.state.Accounts[sh.AccountID]
205			if !ok {
206				return fmt.Errorf("%w: 版税收款账户 %s", ErrNotFound, sh.AccountID)
207			}
208			if !payee.Active {
209				return fmt.Errorf("%w: 版税收款账户 %s", ErrAccountInactive, sh.AccountID)
210			}
211		}
212		return nil
213	}
214	
215	func (r *Registry) replaySetRoyalty(prev request, sig string) (SetRoyaltyResult, error) {
216		if prev.Kind != "royalty_set" || prev.Params != sig {
217			return SetRoyaltyResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
218				ErrRequestConflict, prev.Operator, prev.RequestID)
219		}
220		res := SetRoyaltyResult{SeriesID: prev.SeriesID, Shares: publicShares(prev.Shares), Replayed: true}
221		if prev.Rejected {
222			res.Err = codeErr(prev.Reason)
223			res.Shares = nil
224			return res, res.Err
225		}
226		return res, nil
227	}
228	
229	// ---- 版税计算 ----
230	
231	// royaltyAmount 计算单个收款账户的应付金额：价款乘比例除以 10000 向下
232	// 取整。价款与比例的乘积可能超出 int64，用 big.Int 保证整个价款范围
233	// 内结果准确；结果不超过价款本身，可安全转回 int64。
234	func royaltyAmount(price, rate int64) int64 {
235		amt := big.NewInt(price)
236		amt.Mul(amt, big.NewInt(rate))
237		amt.Div(amt, big.NewInt(RoyaltyRateBase))
238		return amt.Int64()
239	}
240	
241	// newRoyaltyRec 按规则快照计算一笔转让的全部应付明细与剩余收入。
242	// 零金额的应付也保留明细；余款归转让前持有人（ownerID）。
243	func newRoyaltyRec(txSeq int64, itemID, seriesID string, price int64, shares []royaltyShare, ownerID string) royaltyRec {
244		rec := royaltyRec{
245			TxSeq: txSeq, ItemID: itemID, SeriesID: seriesID,
246			Price: price, OwnerID: ownerID,
247		}
248		var total int64
249		for _, sh := range shares {
250			amt := royaltyAmount(price, sh.Rate)
251			rec.Payees = append(rec.Payees, payableLine{
252				AccountID: sh.AccountID, Rate: sh.Rate, Amount: amt,
253			})
254			total += amt
255		}
256		// 比例合计不超过 10000，应付合计不超过价款，余款非负且不溢出。
257		rec.Remainder = price - total
258		return rec
259	}
260	
261	func publicShares(shares []royaltyShare) []RoyaltyShare {
262		out := make([]RoyaltyShare, 0, len(shares))
263		for _, sh := range shares {
264			out = append(out, RoyaltyShare{AccountID: sh.AccountID, Rate: sh.Rate})
265		}
266		return out
267	}
268	
269	func publicPayables(payees []payableLine) []RoyaltyPayable {
270		out := make([]RoyaltyPayable, 0, len(payees))
271		for _, p := range payees {
272			out = append(out, RoyaltyPayable{AccountID: p.AccountID, Rate: p.Rate, Amount: p.Amount})
273		}
274		return out
275	}
276	
277	// royaltyOfTx 返回某笔成功转让落盘的价款、应付明细与余款；旧登记册中
278	// 的转让没有记录，按价款 0、无明细处理。调用时需持有锁。
279	func (r *Registry) royaltyOfTx(txSeq int64) (int64, []RoyaltyPayable, int64) {
280		rec, ok := r.state.Royalties[txSeq]
281		if !ok {
282			return 0, nil, 0
283		}
284		return rec.Price, publicPayables(rec.Payees), rec.Remainder
285	}
286	
287	// ---- 版税查询 ----
288	
289	// GetSeriesRoyalty 查询系列当前的版税规则（按收款账户排序）；未设置或
290	// 已清空时返回空列表。系列不存在时返回包裹 ErrNotFound 的错误。
291	func (r *Registry) GetSeriesRoyalty(seriesID string) ([]RoyaltyShare, error) {
292		r.mu.Lock()
293		defer r.mu.Unlock()
294		if err := r.checkOpen(); err != nil {
295			return nil, err
296		}
297		s, ok := r.state.Series[seriesID]
298		if !ok {
299			return nil, fmt.Errorf("%w: 系列 %s", ErrNotFound, seriesID)
300		}
301		return publicShares(s.Royalty), nil
302	}
303	
304	// RoyaltyHistory 查询系列版税规则的历次变更，按发生先后排列；每条
305	// 记录包含操作者、原因、请求号与前后内容。系列不存在时返回包裹
306	// ErrNotFound 的错误。
307	func (r *Registry) RoyaltyHistory(seriesID string) ([]RoyaltyEvent, error) {
308		r.mu.Lock()
309		defer r.mu.Unlock()
310		if err := r.checkOpen(); err != nil {
311			return nil, err
312		}
313		if _, ok := r.state.Series[seriesID]; !ok {
314			return nil, fmt.Errorf("%w: 系列 %s", ErrNotFound, seriesID)
315		}
316		out := make([]RoyaltyEvent, 0)
317		for _, e := range r.state.RoyaltyEvents {
318			if e.SeriesID != seriesID {
319				continue
320			}
321			out = append(out, RoyaltyEvent{
322				Seq: e.Seq, SeriesID: e.SeriesID, Operator: e.Operator,
323				Reason: e.Reason, RequestID: e.RequestID,
324				Before: publicShares(e.Before), After: publicShares(e.After),
325				OccurredAt: e.OccurredAt,
326			})
327		}
328		return out, nil
329	}
330	
331	// TransferRoyalty 按转让历史序号查询一笔成功转让的版税计算依据与全部
332	// 金额：成交价款、各收款账户应付明细（含零金额）与归转让前持有人的
333	// 剩余收入。序号不是成功的转让记录（不存在或为发行记录）时返回包裹
334	// ErrNotFound 的错误；旧登记册中的转让按价款 0、无应付明细返回。
335	func (r *Registry) TransferRoyalty(txSeq int64) (TransferRoyalty, error) {
336		r.mu.Lock()
337		defer r.mu.Unlock()
338		if err := r.checkOpen(); err != nil {
339			return TransferRoyalty{}, err
340		}
341		if txSeq <= 0 {
342			return TransferRoyalty{}, fmt.Errorf("%w: 转让序号 %d 不合法", ErrInvalidArgument, txSeq)
343		}
344		var entry *historyEntry
345		for i := range r.state.History {
346			if r.state.History[i].Seq == txSeq {
347				entry = &r.state.History[i]
348				break
349			}
350		}
351		if entry == nil || entry.Kind != "transfer" {
352			return TransferRoyalty{}, fmt.Errorf("%w: 转让记录 %d", ErrNotFound, txSeq)
353		}
354		out := TransferRoyalty{
355			TxSeq: txSeq, ItemID: entry.ItemID, OwnerID: entry.FromID,
356			Payables: make([]RoyaltyPayable, 0),
357		}
358		if rec, ok := r.state.Royalties[txSeq]; ok {
359			out.Price = rec.Price
360			out.Payables = publicPayables(rec.Payees)
361			out.Remainder = rec.Remainder
362			out.OwnerID = rec.OwnerID
363		}
364		return out, nil
365	}
366	
367	// PayablesOf 查询某账户作为版税收款账户的全部应付明细，按转让序号
368	// 排列；没有明细时返回空列表。账户不存在时返回包裹 ErrNotFound 的
369	// 错误；停用账户的既有应付记录仍可查询。
370	func (r *Registry) PayablesOf(accountID string) ([]PayableEntry, error) {
371		r.mu.Lock()
372		defer r.mu.Unlock()
373		if err := r.checkOpen(); err != nil {
374			return nil, err
375		}
376		if _, ok := r.state.Accounts[accountID]; !ok {
377			return nil, fmt.Errorf("%w: 账户 %s", ErrNotFound, accountID)
378		}
379		out := make([]PayableEntry, 0)
380		for _, rec := range r.state.Royalties {
381			for _, p := range rec.Payees {
382				if p.AccountID != accountID {
383					continue
384				}
385				out = append(out, PayableEntry{
386					TxSeq: rec.TxSeq, ItemID: rec.ItemID, Price: rec.Price,
387					Rate: p.Rate, Amount: p.Amount,
388				})
389			}
390		}
391		sort.Slice(out, func(i, j int) bool { return out[i].TxSeq < out[j].TxSeq })
392		return out, nil
393	}
394

