10	// 本文件为答复拆分意向补充"保存失败"场景的回归保障，与创建拆分意向
11	// （split_intent_save_failure_test.go）及发行、转让、创建代转授权的同类
12	// 用例行为对齐：参与账户对一个已保存、尚未结束且仍有效的意向首次提交
13	// 同意或拒绝时，这次答复是否生效始终以保存完成为准。新答复尚未写入原
14	// 登记册就发生保存错误时，必须返回实际保存错误——不能返回成功，也不能
15	// 用随后读取数据的错误替代它；结果为空（无意向编号、无状态、业务错误
16	// 为空、不标回放），请求号与意向历史序号都不被这次未保存的答复消耗。
17	// 即使失败后原数据暂时无法读取、状态未能按磁盘重建，同一个仍打开的
18	// 登记册中各方此前已保存的答复、份额与意向结束时间仍保持原样，意向状态
19	// 继续按原有答复、当前持有与账户状态及当前时间判断（不能因这次失败提前
20	// 变为已达成或已拒绝），意向历史不出现这次答复，后续其他操作成功保存也
21	// 不把这次未保存的答复或终结状态带入登记册。
22	//
23	// 失败注入方式与其他场景共用：在临时文件路径 .registry.json.tmp 上预先
24	// 建一个目录，save 在 OpenFile 阶段即以 EISDIR 失败，原快照完好可读；
25	// 另有用例同时破坏数据文件，覆盖"原数据暂时无法读取"的情形。
26	
27	// assertAnswerSaveFailureEmpty 核对答复"保存失败"的返回：error 是保存
28	// 错误而非成功或任何业务拒绝；结果为空——无意向编号、无状态，业务错误
29	// 为空，也不标记为重复返回。
30	func assertAnswerSaveFailureEmpty(t *testing.T, res AnswerSplitIntentResult, err error) {
31		t.Helper()
32		assertSaveFailureError(t, err)
33		if res.IntentID != "" || res.Status != "" || res.Replayed || res.Err != nil {
34			t.Fatalf("保存失败必须返回空结果: %+v", res)
35		}
36	}
