38	// assertAnswerRequestFree 核对请求号未被这次未保存的答复占用、意向历史
39	// 序号未被消耗（在同一个已打开的登记册上检查）。
40	func assertAnswerRequestFree(t *testing.T, r *Registry, req AnswerSplitIntentRequest, wantNextIntentSeq int64) {
41		t.Helper()
42		if _, ok := r.state.Requests[requestKey(req.Operator, req.RequestID)]; ok {
43			t.Fatalf("未保存的答复不应占用请求号 %s", req.RequestID)
44		}
45		if r.state.NextIntentSeq != wantNextIntentSeq {
46			t.Fatalf("NextIntentSeq = %d, want %d", r.state.NextIntentSeq, wantNextIntentSeq)
47		}
48	}
