50	// assertIntentParties 按账户核对意向各方的当前答复，并核对当前状态与
51	// 结束时间。
52	func assertIntentParties(t *testing.T, r *Registry, intentID, status string,
53		wantAnswers map[string]string, wantEnded bool) {
54		t.Helper()
55		in, err := r.GetSplitIntent(intentID)
