58		}
59		if in.Status != status {
60			t.Fatalf("意向 %s 状态 = %s, want %s: %+v", intentID, in.Status, status, in)
61		}
62		if in.EndedAt.IsZero() == wantEnded {
63			t.Fatalf("意向 %s 结束时间异常: %+v", intentID, in)
64		}
65		got := make(map[string]string, len(in.Shares))
66		for _, p := range in.Shares {
67			got[p.AccountID] = p.Answer
68		}
69		for acct, want := range wantAnswers {
70			if got[acct] != want {
71				t.Fatalf("账户 %s 的答复 = %q, want %q（各方答复 %v）", acct, got[acct], want, got)
