551		}
552		// 业务拒绝不新增意向历史，bob 的答复也未被改变。
553		assertIntentParties(t, r, "it1", SplitPending, map[string]string{"bob": SplitAnswerAgree}, false)
554		if evs, _ := r.SplitIntentHistory("i1"); len(evs) != 2 {
555			t.Fatalf("业务拒绝后意向历史仍应是 2 条: %+v", evs)
556		}
557	}
558	
559	// TestAnswerSplitIntentEndedRejectSaveFailure 覆盖：对已拒绝意向的答复本应
560	// 返回 ErrSplitIntentRejected，但这次拒绝结果保存失败时返回实际保存错误、
561	// 结果为空、不占用请求号；恢复后重提重新保存该拒绝。
562	func TestAnswerSplitIntentEndedRejectSaveFailure(t *testing.T) {
563		r := mustCreate(t, tempDir(t))
564		answerSaveFailureWorld(t, r)
565		// carol 拒绝，方案终结为已拒绝（已保存）。
566		if _, err := r.AnswerSplitIntent(answerReq("carol", "it1", "ans-carol", false)); err != nil {
567			t.Fatal(err)
568		}
569		req := answerReq("bob", "it1", "ans-bob-after-reject", true)
570	
571		blockBatchSave(t, r)
572		res, err := r.AnswerSplitIntent(req)
573		assertAnswerSaveFailureEmpty(t, res, err)
574		assertAnswerRequestFree(t, r, req, 2)
575	
576		restoreBatchSave(t, r)
577		res, err = r.AnswerSplitIntent(req)
578		if !errors.Is(err, ErrSplitIntentRejected) {
579			t.Fatalf("重提应返回 ErrSplitIntentRejected: %v", err)
580		}
581		if res.Replayed || res.IntentID != "it1" || !errors.Is(res.Err, ErrSplitIntentRejected) {
582			t.Fatalf("已拒绝意向答复的重提结果异常: %+v", res)
583		}
584		res, err = r.AnswerSplitIntent(req)
585		if !errors.Is(err, ErrSplitIntentRejected) || !res.Replayed {
586			t.Fatalf("再次提交应回放已保存的拒绝: %+v, err %v", res, err)
587		}
588	}
589	
590	// TestAnswerSplitIntentRepeatSaveFailure 覆盖：重复相同答复只登记请求结果、
591	// 不新增变更记录；该请求结果保存失败时同样返回实际保存错误、结果为空、
592	// 不占用请求号，恢复后重提正常返回当前状态（不标回放），此后回放。
593	func TestAnswerSplitIntentRepeatSaveFailure(t *testing.T) {
594		r := mustCreate(t, tempDir(t))
595		answerSaveFailureWorld(t, r)
596		if _, err := r.AnswerSplitIntent(answerReq("bob", "it1", "ans-bob", true)); err != nil {
597			t.Fatal(err)
598		}
599		req := answerReq("bob", "it1", "ans-bob-repeat", true)
600	
601		blockBatchSave(t, r)
602		res, err := r.AnswerSplitIntent(req)
603		assertAnswerSaveFailureEmpty(t, res, err)
604		assertAnswerRequestFree(t, r, req, 2)
605		// 重复答复本就不新增历史，失败后历史仍是 create + bob 首次答复。
606		if evs, _ := r.SplitIntentHistory("i1"); len(evs) != 2 {
607			t.Fatalf("重复答复保存失败后历史应仍是 2 条: %+v", evs)
608		}
609	
610		restoreBatchSave(t, r)
611		// carol 尚未答复：重提重复答复返回待确认，首次不标回放，不新增历史。
612		res, err = r.AnswerSplitIntent(req)
613		if err != nil || res.Replayed || res.IntentID != "it1" || res.Status != SplitPending {
614			t.Fatalf("恢复后重提应返回当前状态: %+v, err %v", res, err)
615		}
616		if evs, _ := r.SplitIntentHistory("i1"); len(evs) != 2 {
617			t.Fatalf("重复答复重提不应新增历史: %+v", evs)
618		}
619		// 保存成功后相同请求回放首次结果。
620		res, err = r.AnswerSplitIntent(req)
621		if err != nil || !res.Replayed || res.Status != SplitPending {
622			t.Fatalf("成功后重提应回放: %+v, err %v", res, err)
623		}
624	}
625	
626	// TestAnswerSplitIntentSaveFailureAfterReopen 覆盖磁盘视角：原数据可读时
627	// 保存失败后关闭重开，看到的仍是答复前状态——未保存的答复不存在、请求号
628	// 未占用；恢复保存后用原请求重提正常生效。
629	func TestAnswerSplitIntentSaveFailureAfterReopen(t *testing.T) {
630		dir := tempDir(t)
631		r := mustCreate(t, dir)
632		answerSaveFailureWorld(t, r)
633		if _, err := r.AnswerSplitIntent(answerReq("bob", "it1", "ans-bob", true)); err != nil {
634			t.Fatal(err)
635		}
636		req := answerReq("carol", "it1", "ans-carol", true)
637	
638		blockBatchSave(t, r)
639		res, err := r.AnswerSplitIntent(req)
640		assertAnswerSaveFailureEmpty(t, res, err)
641	
642		if err := r.Close(); err != nil {
643			t.Fatal(err)
644		}
645		r2, err := Open(dir)
646		if err != nil {
647			t.Fatalf("失败后原登记册必须仍能正常读取: %v", err)
648		}
649		t.Cleanup(func() { _ = r2.Close() })
650		assertIntentParties(t, r2, "it1", SplitPending, map[string]string{
651			"alice": SplitAnswerAgree, "bob": SplitAnswerAgree, "carol": "",
652		}, false)
653		if _, ok := r2.state.Requests[requestKey(req.Operator, req.RequestID)]; ok {
654			t.Fatal("重开后未保存的答复不应占用请求号")
655		}
656		if r2.state.NextIntentSeq != 2 {
657			t.Fatalf("重开后 NextIntentSeq = %d, want 2", r2.state.NextIntentSeq)
658		}
659		if evs, _ := r2.SplitIntentHistory("i1"); len(evs) != 2 {
660			t.Fatalf("重开后历史应仍是 2 条: %+v", evs)
661		}
662	
663		restoreBatchSave(t, r2)
664		res2, err := r2.AnswerSplitIntent(req)
665		if err != nil || res2.Replayed || res2.Status != SplitAgreed {
666			t.Fatalf("重开后重提应正常生效: %+v, err %v", res2, err)
667		}
668		res2, err = r2.AnswerSplitIntent(req)
669		if err != nil || !res2.Replayed || res2.Status != SplitAgreed {
670			t.Fatalf("成功后重提应回放: %+v, err %v", res2, err)
671		}
672	}
